data.query:
query ReceiptLine($where: ReceiptLineWhereInput, $orderBy: [ReceiptLineOrderByInput!], $first: Int, $after: String) {
  receiptLine(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    total
    edges {
      node {
        id
        numberOfInventory
        addToHandlingUnit
        quantity { value unitId }
        lotId
        productId
        product{ forceHold }
        receiptId
        receipt { dockStorageUnitId }
        receiptException{ id }
        receiptLineOrderLineReleases{
          edges{
            node{
              orderLineReleaseId
            }
          }
        }
      }
    }
  }
}

data.transform:
(
 
  $payloads := receiptLine.edges.node.(
    $receiptLine := $;
    $inventoryQuantity := quantity.value / numberOfInventory;
    $newHandlingUnitId := $cuid();

    {
      "receiptLinePayload":{
        "where":{ "id": id },
        "update": { "receiptStatusId": "confirmed" }
      },

      "inventoryPayload":[1..numberOfInventory].{
        "productId":  $receiptLine.productId,
        "inventoryStatusId": $receiptLine.receiptException? "damaged" : $receiptLine.product.forceHold? "hold" : "ok" ,
        "storageUnitId":  $receiptLine.receipt.dockStorageUnitId,
        "quantity":  $inventoryQuantity,
        "shippable": true,
        "receiptLineId":  $receiptLine.id,
        "handlingUnitId": $receiptLine.addToHandlingUnit? $newHandlingUnitId,
        "lotId": $coalesce([$receiptLine.lotId]),
        "processId": "receive"
      },

      "handlingUnitPayload": addToHandlingUnit? {
        "create":{
          "id": $newHandlingUnitId
        }
      } : []
  });

  {
    "receiptLinePayload": [$payloads.receiptLinePayload],
    "inventoryPayload": [$payloads.inventoryPayload],
    "handlingUnitPayload": [$payloads.handlingUnitPayload] 
  }

)

data.responseTransform:
{
  "success": false,
  "message": "Not all receipt lines can be confirmed."
}

